const all = $input.all().map(i => i.json);
const err = all.filter(j => !/^ecrite/.test(String(j.note_interfast)));
return [{ json: { total: all.length, ok: all.length - err.length, erreurs: err.length, detail_erreurs: err.slice(0, 30) } }];

const src = $('Preparer reformatage').all();
const out = [];
$input.all().forEach((it, i) => {
  const s = src[i].json;
  const liste = (it.json && it.json.items) || [];
  const note = liste.find(a => a.type === 'note' && String((a.data && a.data.content) || '').startsWith('Historique ClimatPro avant Interfast') && String(a.data.content).includes(s.premier));
  if (note) out.push({ json: Object.assign({}, s, { note_id: note.id }) });
});
return out;

// Construit la note d'historique (sans aucun montant) pour les clients sur ou valides OK. Aucune IA.
const LOT = 2000;
const fr = d => { const m = String(d || '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? m[3] + '/' + m[2] + '/' + m[1] : ''; };
const court = s => { s = String(s || '').replace(/\s+/g, ' ').trim().replace(/[.;]+$/, ''); return s.length > 120 ? s.slice(0, 117).replace(/\s+\S*$/, '') + '...' : s; };
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().replace(/[^A-Z0-9]+/g, ' ').trim();
function construire(fac) {
  const vus = new Set(); const items = []; const mat = new Map();
  for (const f of fac) {
    if (vus.has(f.numero)) continue;
    vus.add(f.numero);
    items.push({ t: [fr(f.date_facture), f.numero, court(f.description)].filter(Boolean).join(' - '), lien: f.file_id ? 'https://drive.google.com/file/d/' + f.file_id + '/view' : '' });
    const m = [f.marque, f.modele].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim();
    const k = norm(m);
    if (k && !mat.has(k)) mat.set(k, m.toUpperCase() === m || m.toLowerCase() === m ? m.toUpperCase() : m);
  }
  const cles = [...mat.keys()];
  const matF = cles.filter(k => !cles.some(o => o !== k && o.startsWith(k + ' '))).map(k => mat.get(k)).slice(0, 8);
  const n = items.length;
  let c = 'Historique ClimatPro avant Interfast (archives factures) : ' + n + ' facture' + (n > 1 ? 's' : '') + ' au total';
  for (const i of items) c += '\n\n' + i.t + (i.lien ? '\n' + i.lien : '');
  if (matF.length) c += '\n\nMatériel connu : ' + matF.join(', ');
  return { n, contenu: c };
}
const parCle = {};
for (const it of $('Lire index').all()) {
  const r = it.json || {};
  if (String(r.statut || '') !== 'ok') continue;
  const dossier = String(r.dossier_client || '').trim();
  const fourreTout = !dossier || /ANCIENS CLIENTS|racine/i.test(dossier);
  const cle = fourreTout ? (dossier || '(racine)') + ' / ' + String(r.client || '').trim() : dossier;
  (parCle[cle] = parCle[cle] || []).push(r);
}
const out = [];
for (const it of $('Lire correspondance').all()) {
  if (out.length >= LOT) break;
  const c = it.json || {};
  const decision = String(c.decision_laurent || '').trim().toUpperCase();
  if (String(c.note_interfast || '').trim()) continue;
  if (!String(c.interfast_id || '').trim()) continue;
  if (decision === 'NON') continue;
  if (!(decision === 'OK' || (decision === '' && c.statut === 'sur'))) continue;
  // Garde-fou : fiche Interfast dont le nom est juste une ville (ex : LE CANNET) -> on ne devine pas, sauf OK de Laurent
  const nomIF = norm(c.interfast_nom);
  const villesC = String(c.villes || '').split(/[,;\/]/).map(norm).concat([norm(c.interfast_ville)]).filter(Boolean);
  if (decision !== 'OK' && villesC.includes(nomIF)) continue;
  const fac = (parCle[String(c.cle || '').trim()] || []).slice().sort((a, b) => String(a.date_facture).localeCompare(String(b.date_facture)));
  if (!fac.length) continue;
  const r = construire(fac);
  out.push({ json: { cle: c.cle, interfast_id: String(c.interfast_id).trim(), interfast_nom: c.interfast_nom, nb: r.n, contenu: r.contenu } });
}
return out;

// Reecrit les notes deja posees (ecrite ...) au nouveau format. MODE_HTML = cles a tester en HTML.
const MODE_HTML = ['NAVIGAIR'];
const EXCLURE = ['FREDERIC M FRANCE - LE CANNET'];
const fr = d => { const m = String(d || '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? m[3] + '/' + m[2] + '/' + m[1] : ''; };
const court = s => { s = String(s || '').replace(/\s+/g, ' ').trim().replace(/[.;]+$/, ''); return s.length > 120 ? s.slice(0, 117).replace(/\s+\S*$/, '') + '...' : s; };
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().replace(/[^A-Z0-9]+/g, ' ').trim();
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
function construire(fac, html) {
  const vus = new Set(); const items = []; const mat = new Map();
  for (const f of fac) {
    if (vus.has(f.numero)) continue;
    vus.add(f.numero);
    items.push({ num: String(f.numero), t: [fr(f.date_facture), f.numero, court(f.description)].filter(Boolean).join(' - '), lien: f.file_id ? 'https://drive.google.com/file/d/' + f.file_id + '/view' : '' });
    const m = [f.marque, f.modele].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim();
    const k = norm(m);
    if (k && !mat.has(k)) mat.set(k, m.toUpperCase() === m || m.toLowerCase() === m ? m.toUpperCase() : m);
  }
  const cles = [...mat.keys()];
  const matF = cles.filter(k => !cles.some(o => o !== k && o.startsWith(k + ' '))).map(k => mat.get(k)).slice(0, 8);
  const n = items.length;
  const titre = 'Historique ClimatPro avant Interfast (archives factures) : ' + n + ' facture' + (n > 1 ? 's' : '') + ' au total';
  let c;
  if (html) {
    c = '<p><strong>' + esc(titre) + '</strong></p>';
    for (const i of items) c += '<p>' + esc(i.t) + (i.lien ? '<br><a href="' + i.lien + '" target="_blank">' + i.lien + '</a>' : '') + '</p>';
    if (matF.length) c += '<p>Matériel connu : ' + esc(matF.join(', ')) + '</p>';
  } else {
    c = titre;
    for (const i of items) c += '\n\n' + i.t + (i.lien ? '\n' + i.lien : '');
    if (matF.length) c += '\n\nMatériel connu : ' + matF.join(', ');
  }
  return { n, contenu: c, premier: items.length ? items[0].num : '' };
}
const parCle = {};
for (const it of $('Lire index 2').all()) {
  const r = it.json || {};
  if (String(r.statut || '') !== 'ok') continue;
  const dossier = String(r.dossier_client || '').trim();
  const fourreTout = !dossier || /ANCIENS CLIENTS|racine/i.test(dossier);
  const cle = fourreTout ? (dossier || '(racine)') + ' / ' + String(r.client || '').trim() : dossier;
  (parCle[cle] = parCle[cle] || []).push(r);
}
const out = [];
for (const it of $('Lire correspondance 2').all()) {
  const c = it.json || {};
  const cle = String(c.cle || '').trim();
  const st = String(c.note_interfast || '').trim();
  if (!/^ecrite/.test(st) || / v2$/.test(st)) continue;
  if (EXCLURE.includes(cle)) continue;
  if (!String(c.interfast_id || '').trim()) continue;
  const fac = (parCle[cle] || []).slice().sort((a, b) => String(a.date_facture).localeCompare(String(b.date_facture)));
  if (!fac.length) continue;
  const html = MODE_HTML.includes(cle);
  const r = construire(fac, html);
  out.push({ json: { cle: c.cle, interfast_id: String(c.interfast_id).trim(), nb: r.n, premier: r.premier, contenu: r.contenu, statut_avant: st, html } });
}
return out;

const src = $('Preparer notes').item.json;
const code = Number($json.statusCode || 0);
const ok = code >= 200 && code < 300;
const jour = $now.setZone('Europe/Paris').toFormat('yyyy-LL-dd');
return { json: { cle: src.cle, note_interfast: ok ? 'ecrite ' + jour : 'ERREUR ' + code } };

const src = $('Choisir note').item.json;
const code = Number($json.statusCode || 0);
const ok = code >= 200 && code < 300;
return { json: { cle: src.cle, note_interfast: ok ? src.statut_avant + ' v2' + (src.html ? ' html' : '') : src.statut_avant + ' ERREUR v2 ' + code } };

const num = v => { const x = parseFloat(String(v == null ? '' : v).replace(/\s/g, '').replace(',', '.')); return isFinite(x) ? x : null; };
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim() || '(vide)';
const med = a => { if (!a.length) return null; const b = a.slice().sort((x, y) => x - y); const m = Math.floor(b.length / 2); return Math.round(b.length % 2 ? b[m] : (b[m - 1] + b[m]) / 2); };
const types = {}; const an = {}; const anType = {}; const mois = {}; const anMois = {}; const pu = {};
let sansMontant = 0, sansDate = 0, n = 0;
const add = (o, k, f) => { o[k] = o[k] || f(); return o[k]; };
for (const it of $input.all()) {
  const r = it.json || {};
  if (String(r.statut || '') !== 'ok') continue;
  n++;
  const m = String(r.date_facture || '').match(/^(\d{4})-(\d{2})/);
  if (!m) { sansDate++; continue; }
  const y = m[1], mo = m[2];
  const av = String(r.type_doc || '').toUpperCase().startsWith('AV') || /^AV/i.test(String(r.numero || ''));
  let ht = num(r.montant_ht);
  if (ht == null) { sansMontant++; ht = 0; }
  const signe = av ? -Math.abs(ht) : ht;
  const t = norm(r.type_intervention);
  const T = add(types, t, () => ({ nb: 0, ca: 0 })); T.nb++; T.ca += signe;
  const A = add(an, y, () => ({ fa: 0, av: 0, ca: 0, paniers: [] }));
  if (av) A.av++; else { A.fa++; if (ht > 0) A.paniers.push(ht); }
  A.ca += signe;
  if (!av) {
    const AT = add(anType, y + '|' + t, () => ({ nb: 0, ca: 0, p: [] })); AT.nb++; AT.ca += ht; if (ht > 0) AT.p.push(ht);
    const M = add(mois, mo + '|' + t, () => ({ nb: 0, ca: 0 })); M.nb++; M.ca += ht;
    const AM = add(anMois, y + '-' + mo, () => ({ nb: 0, ca: 0 })); AM.nb++; AM.ca += ht;
    const u = num(r.nb_unites_int), kw = num(r.puissance_kw);
    if (ht > 0 && u && u > 0) { const P = add(pu, y + '|' + t, () => ({ parUnite: [], parKw: [] })); P.parUnite.push(ht / u); if (kw && kw > 0) P.parKw.push(ht / kw); }
  }
}
const R = x => Math.round(x);
return [{ json: {
  n, sansMontant, sansDate,
  types: Object.entries(types).sort((a, b) => b[1].nb - a[1].nb).map(([k, v]) => ({ type: k, nb: v.nb, ca: R(v.ca) })),
  annees: Object.keys(an).sort().map(y => ({ an: y, fa: an[y].fa, av: an[y].av, ca: R(an[y].ca), panier_med: med(an[y].paniers) })),
  anType: Object.keys(anType).sort().map(k => { const [y, t] = k.split('|'); const v = anType[k]; return { an: y, type: t, nb: v.nb, ca: R(v.ca), med: med(v.p) }; }),
  mois: Object.keys(mois).sort().map(k => { const [mo, t] = k.split('|'); return { mois: mo, type: t, nb: mois[k].nb, ca: R(mois[k].ca) }; }),
  anMois: Object.keys(anMois).sort().map(k => ({ m: k, nb: anMois[k].nb, ca: R(anMois[k].ca) })),
  prixUnitaires: Object.keys(pu).sort().map(k => { const [y, t] = k.split('|'); const v = pu[k]; return { an: y, type: t, n: v.parUnite.length, med_par_unite: med(v.parUnite), n_kw: v.parKw.length, med_par_kw: med(v.parKw) }; })
} }];
